pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 v1, uint256 v2) internal {
        vm.assume(v1 != v2);
        try c.SetMinSum(v1) {} catch { return; }
        uint256 m1;
        try c.MinSum() returns (uint256 __r) { m1 = __r; } catch { return; }
        try c.SetMinSum(v2) {} catch { return; }
        uint256 m2;
        try c.MinSum() returns (uint256 __r) { m2 = __r; } catch { return; }
        assertTrue(m1 == v1 && m2 == v2);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
